"""
Data models module for Fashion Trend Monitor.

Defines dataclass structures for Product and AIAnalysis objects.
The Product dataclass acts as the single source of truth across the pipeline.
"""

from dataclasses import dataclass, field
from typing import Optional, Dict, Any, List


@dataclass
class AIAnalysis:
    """Represents visual fashion analysis generated by NVIDIA NIM API."""
    product_category: str = "other"
    design_pattern: str = "N/A"
    bullet_summary: List[str] = field(default_factory=list)
    confidence_score: str = "N/A"
    category_specific_info: Dict[str, str] = field(default_factory=dict)
    
    # legacy fields to avoid breaking old data from JSON storage
    fabric_info: str = "N/A"
    pattern_info: str = "N/A"
    textile_info: str = "N/A"
    construction_info: str = "N/A"
    summary: str = "No analysis available."
    extracted_attributes: Dict[str, str] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        """Convert AIAnalysis object to dictionary format."""
        return {
            "product_category": self.product_category,
            "design_pattern": self.design_pattern,
            "bullet_summary": self.bullet_summary,
            "confidence_score": self.confidence_score,
            "category_specific_info": self.category_specific_info,
            "fabric_info": self.fabric_info,
            "pattern_info": self.pattern_info,
            "textile_info": self.textile_info,
            "construction_info": self.construction_info,
            "summary": self.summary,
            "extracted_attributes": self.extracted_attributes,
        }

    @classmethod
    def from_dict(cls, data: Optional[Dict[str, Any]]) -> "AIAnalysis":
        """Instantiate AIAnalysis object from a dictionary. Supports both new and legacy keys."""
        if not data:
            return cls()
        bullets = data.get("bullet_summary", [])
        if isinstance(bullets, str):
            bullets = [b.strip() for b in bullets.split(",") if b.strip()]
            
        return cls(
            product_category=data.get("product_category", "other"),
            design_pattern=data.get("design_pattern", data.get("pattern_info", "N/A")),
            bullet_summary=bullets if isinstance(bullets, list) else [],
            confidence_score=data.get("confidence_score", "N/A"),
            category_specific_info=data.get("category_specific_info", data.get("extracted_attributes", {})),
            fabric_info=data.get("fabric_info", "N/A"),
            pattern_info=data.get("pattern_info", "N/A"),
            textile_info=data.get("textile_info", "N/A"),
            construction_info=data.get("construction_info", "N/A"),
            summary=data.get("summary", "No analysis available."),
            extracted_attributes=data.get("extracted_attributes", {}),
        )


@dataclass
class Product:
    """
    Represents a fashion product item throughout the monitoring pipeline.
    Progressively enriched as it passes through scraping, detail-page scraping,
    screenshot capture, and AI analysis.
    """
    art_no: str
    name: str
    price: str
    product_url: str
    image_url: str
    category: str = "Men"
    # Populated from AI extracted_attributes after analysis (optional mirrors)
    composition: str = ""          # e.g. "Cotton 100%"
    material_type: str = ""        # e.g. "Cotton, Jersey"
    description: str = ""          # free-text blurb from Description & Fit accordion
    fit: str = ""                  # e.g. "Relaxed fit"
    fit_details: Dict[str, str] = field(default_factory=dict)  # legacy; prefer AI extracted_attributes
    # Raw accordion text from Camoufox detail scrape (Description & Fit + Material & Care).
    # AI uses this as sole source of truth for extracted_attributes — no regex field parsing.
    raw_page_text: str = ""
    screenshot_path: Optional[str] = None
    ai_analysis: Optional[AIAnalysis] = None

    def to_dict(self) -> Dict[str, Any]:
        """Convert Product object to serializable dictionary format."""
        return {
            "art_no": self.art_no,
            "name": self.name,
            "price": self.price,
            "product_url": self.product_url,
            "image_url": self.image_url,
            "category": self.category,
            "composition": self.composition,
            "material_type": self.material_type,
            "description": self.description,
            "fit": self.fit,
            "fit_details": self.fit_details,
            "raw_page_text": self.raw_page_text,
            "screenshot_path": self.screenshot_path,
            "ai_analysis": self.ai_analysis.to_dict() if self.ai_analysis else None,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Product":
        """Instantiate Product object from a dictionary."""
        ai_data = data.get("ai_analysis")
        ai_obj = AIAnalysis.from_dict(ai_data) if ai_data else None
        # Support legacy individual fields by folding them into fit_details
        fit_details = data.get("fit_details", {}) or {}
        for legacy_key, display_key in [
            ("neckline", "Neckline"),
            ("sleeve_length", "Sleeve Length"),
            ("garment_length", "Length"),
        ]:
            if data.get(legacy_key) and display_key not in fit_details:
                fit_details[display_key] = data[legacy_key]
        return cls(
            art_no=str(data["art_no"]),
            name=data.get("name", "Unknown Product"),
            price=data.get("price", "N/A"),
            product_url=data.get("product_url", ""),
            image_url=data.get("image_url", ""),
            category=data.get("category", "Men"),
            composition=data.get("composition", ""),
            material_type=data.get("material_type", ""),
            description=data.get("description", ""),
            fit=data.get("fit", ""),
            fit_details=fit_details,
            raw_page_text=data.get("raw_page_text", ""),
            screenshot_path=data.get("screenshot_path"),
            ai_analysis=ai_obj,
        )